create or replace function public.casino_settle_crash(p_user_id uuid,p_round_ref text,p_bet_amount numeric,p_target_multiplier numeric,p_crash_multiplier numeric,p_did_cashout boolean,p_payout_amount numeric,p_server_seed_hash text,p_server_seed text,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_existing public.crash_bets%rowtype; v_balance numeric; v_bonus numeric; v_source text; v_bet jsonb; v_settle jsonb; v_effects jsonb; v_bet_id uuid; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if nullif(trim(p_round_ref),'') is null then raise exception 'ROUND_REF_REQUIRED'; end if; if coalesce(p_bet_amount,0)<=0 then raise exception 'INVALID_BET'; end if; if coalesce(p_payout_amount,0)<0 then raise exception 'INVALID_PAYOUT'; end if; if not coalesce(p_did_cashout,false) and coalesce(p_payout_amount,0)<>0 then raise exception 'INVALID_BUST_PAYOUT'; end if; perform pg_advisory_xact_lock(hashtextextended('crash:'||p_round_ref,0)); select * into v_existing from public.crash_bets where ref_id=p_round_ref limit 1; if found then if v_existing.user_id<>p_user_id then raise exception 'ROUND_REF_CONFLICT'; end if; return jsonb_build_object('ok',true,'idempotent',true,'bet_id',v_existing.id,'payout',v_existing.payout,'did_cashout',v_existing.did_cashout); end if; insert into public.balances(user_id,balance,bonus_balance,locked_balance,commission_balance,currency) values(p_user_id,0,0,0,0,'MXN') on conflict(user_id) do nothing; select balance,bonus_balance into v_balance,v_bonus from public.balances where user_id=p_user_id for update; if coalesce(v_balance,0)>=p_bet_amount then v_source:='balance'; v_bet:=public.wallet_apply_delta(p_user_id,-p_bet_amount,0,p_bet_amount,'crash_bet_balance',p_round_ref||':bet','internal_game',jsonb_build_object('game','crash','source','balance')); elsif coalesce(v_bonus,0)>=p_bet_amount then v_source:='bonus'; v_bet:=public.wallet_apply_delta(p_user_id,0,-p_bet_amount,p_bet_amount,'crash_bet_bonus',p_round_ref||':bet','internal_game',jsonb_build_object('game','crash','source','bonus')); else raise exception 'INSUFFICIENT_FUNDS'; end if; if coalesce(v_bet->>'ok','false')<>'true' then raise exception 'BET_WALLET_FAILED'; end if; insert into public.crash_bets(user_id,bet_amount,target_multiplier,crash_multiplier,did_cashout,payout,ref_id,server_seed_hash,server_seed,metadata) values(p_user_id,round(p_bet_amount,2),p_target_multiplier,p_crash_multiplier,p_did_cashout,round(p_payout_amount,2),p_round_ref,p_server_seed_hash,p_server_seed,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('wallet_source',v_source)) returning id into v_bet_id; v_settle:=public.wallet_apply_delta(p_user_id,p_payout_amount,0,-p_bet_amount,case when p_did_cashout then 'crash_cashout' else 'crash_bust' end,p_round_ref||':settle','internal_game',jsonb_build_object('game','crash','did_cashout',p_did_cashout,'target_multiplier',p_target_multiplier)); if coalesce(v_settle->>'ok','false')<>'true' then raise exception 'SETTLE_WALLET_FAILED'; end if; v_effects:=public.record_wager_effects(p_user_id,p_bet_amount,'crash:'||p_round_ref,'crash',0.005); if coalesce(v_effects->>'ok','false')<>'true' then raise exception 'WAGER_EFFECTS_FAILED'; end if; return jsonb_build_object('ok',true,'idempotent',false,'bet_id',v_bet_id,'source',v_source,'bet_wallet',v_bet,'settle_wallet',v_settle,'effects',v_effects); end; $$;
create or replace function public.casino_settle_taco_slot(p_user_id uuid,p_round_ref text,p_bet_amount numeric,p_payout_amount numeric,p_multiplier numeric,p_reels jsonb,p_server_seed_hash text,p_server_seed text,p_client_seed text,p_nonce bigint,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_existing public.slot_spins%rowtype; v_balance numeric; v_bonus numeric; v_source text; v_bet jsonb; v_payout jsonb; v_effects jsonb; v_spin_id uuid; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if nullif(trim(p_round_ref),'') is null then raise exception 'ROUND_REF_REQUIRED'; end if; if coalesce(p_bet_amount,0)<=0 then raise exception 'INVALID_BET'; end if; if coalesce(p_payout_amount,0)<0 then raise exception 'INVALID_PAYOUT'; end if; if coalesce(p_nonce,0)<=0 then raise exception 'INVALID_NONCE'; end if; perform pg_advisory_xact_lock(hashtextextended('taco_slot:'||p_round_ref,0)); select * into v_existing from public.slot_spins where round_ref=p_round_ref limit 1; if found then if v_existing.user_id<>p_user_id then raise exception 'ROUND_REF_CONFLICT'; end if; return jsonb_build_object('ok',true,'idempotent',true,'spin_id',v_existing.id,'nonce',v_existing.nonce,'payout',v_existing.payout_amount); end if; insert into public.balances(user_id,balance,bonus_balance,locked_balance,commission_balance,currency) values(p_user_id,0,0,0,0,'MXN') on conflict(user_id) do nothing; select balance,bonus_balance into v_balance,v_bonus from public.balances where user_id=p_user_id for update; if coalesce(v_balance,0)>=p_bet_amount then v_source:='balance'; v_bet:=public.wallet_apply_delta(p_user_id,-p_bet_amount,0,0,'taco_slot_bet_balance',p_round_ref||':bet','internal_game',jsonb_build_object('game','taco_slot','source','balance')); elsif coalesce(v_bonus,0)>=p_bet_amount then v_source:='bonus'; v_bet:=public.wallet_apply_delta(p_user_id,0,-p_bet_amount,0,'taco_slot_bet_bonus',p_round_ref||':bet','internal_game',jsonb_build_object('game','taco_slot','source','bonus')); else raise exception 'INSUFFICIENT_FUNDS'; end if; if coalesce(v_bet->>'ok','false')<>'true' then raise exception 'BET_WALLET_FAILED'; end if; if p_payout_amount>0 then v_payout:=public.wallet_apply_delta(p_user_id,p_payout_amount,0,0,'taco_slot_win',p_round_ref||':payout','internal_game',jsonb_build_object('game','taco_slot','multiplier',p_multiplier)); if coalesce(v_payout->>'ok','false')<>'true' then raise exception 'PAYOUT_WALLET_FAILED'; end if; end if; insert into public.slot_spins(user_id,bet_amount,payout_amount,multiplier,reels,server_seed_hash,server_seed,client_seed,nonce,metadata,round_ref) values(p_user_id,round(p_bet_amount,2),round(p_payout_amount,2),p_multiplier,p_reels,p_server_seed_hash,p_server_seed,p_client_seed,p_nonce,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('wallet_source',v_source),p_round_ref) returning id into v_spin_id; v_effects:=public.record_wager_effects(p_user_id,p_bet_amount,'slot:'||p_round_ref,'taco_slot',0.005); if coalesce(v_effects->>'ok','false')<>'true' then raise exception 'WAGER_EFFECTS_FAILED'; end if; return jsonb_build_object('ok',true,'idempotent',false,'spin_id',v_spin_id,'nonce',p_nonce,'source',v_source,'bet_wallet',v_bet,'payout_wallet',v_payout,'effects',v_effects); end; $$;
